F={}
def f(k,**kw): F[k]=kw
# ---------- Panoramax, DK19 (Wasilków–Czarna Białostocka, Puszcza Knyszyńska) ----------
f('PX03',typ='krawędź',el='DK19, skraj boru z płaszczem krzewów',opis='Dwupasowa droga, z naprzeciwka ciemny van i kolumna aut. Po prawej za trawiastym poboczem pas liściastych krzewów i młodych drzewek (zwarty, do ziemi), za nim wyższa ściana boru iglastego z ząbkowaną linią wierzchołków. Po lewej wysokie drzewa liściaste i sosny tuż przy jezdni, pnie w cieniu.',gat='iglaste w tle (sosna/świerk — rodzaj z tej odległości UNVERIFIED), płaszcz liściasty',H=('płaszcz 3–5; ściana 15–20','krotność wysokości vana z naprzeciwka (~1,9 m) przeniesiona na linię krzewów; ±40 %'),plaszcz=('5–10','ciągły pas krzewów/młodnika liściastego przed ścianą'))
f('PX06',typ='krawędź',el='DK19, korytarz w lesie',opis='Prosta droga w korytarzu leśnym, auto przed kamerą. Obie strony: wysoka zwarta ściana lasu; po lewej sosny pod światło, po prawej sosny z wysoko osadzoną koroną, a pod nimi liściasty podrost wypełniający ścianę do ziemi — pni przy krawędzi prawie nie widać. Trawiaste pobocze-skarpa szer. kilku metrów.',gat='sosna + podrost liściasty',H=('20–25','ściana ~12–15× wysokość auta (~1,45 m) na tej samej głębi; ±30 %'),plaszcz=('0–2','brak osobnego pasa krzewów; podrost liściasty w linii pni, liście do ziemi'))
f('PX10',typ='krawędź',el='DK19, skraj z pasem krzewów',opis='Droga z autami z naprzeciwka. Po prawej trawiaste pobocze, potem pas krzewów i młodych drzewek liściastych, za nim wysokie drzewa (smukła liściasta korona na pierwszym planie, sosna z prawej). Po lewej sosny o widocznych pniach i ażurowych koronach.',gat='sosna, liściaste (brzoza/osika — UNVERIFIED)',H=('płaszcz 2–4; drzewa 20–25','krotność wysokości auta; ±30 %'),plaszcz=('4–8','ciągły pas krzewów 2–4 m wys. między poboczem a drzewostanem'))
f('PX14',typ='krawędź',el='DK19, las przy drodze z barierami',opis='Droga ze stalowymi barierami po obu stronach. Po prawej ciemna, zwarta ściana iglasta schodząca nisko, bez osobnego pasa krzewów; po lewej drzewa liściaste i sosna, trawiasta skarpa.',gat='iglaste (świerk/sosna)',H=('18–24','krotność wysokości auta przed kamerą; ±30 %'),plaszcz=('0','brak płaszcza — korony do bariery'))
f('PX16',typ='krawędź',el='DK19, sosny z podrostem',opis='Po prawej sosny o ciemnych pniach i parasolowatych koronach wysoko, u podstawy młode liściaste i krzewy; trawiaste pobocze. Po lewej brzozy i mieszany drzewostan. Z naprzeciwka ciemny SUV.',gat='sosna, brzoza',H=('20–25','krotność wysokości SUV-a (~1,65 m); ±30 %'),plaszcz=('1–3','nieciągłe kępy krzewów 2–4 m u podstawy pni'))
f('PX22',typ='krawędź',el='DK19, sosny „kolumnowe” na skarpie',opis='Szeroka jezdnia z wysokimi latarniami na łukowych wysięgnikach. Po prawej trawiasta skarpa z siatkowym ogrodzeniem na koronie i rząd sosen: gołe pomarańczowo-rude pnie na ~2/3 wysokości, korony tylko w górnej części. Po lewej za barierą drągowina sosnowa z widocznymi pniami. Bezchmurnie, niskie słońce.',gat='sosna',H=('15–20','porównanie z latarnią na pierwszym planie ('+LAMP+' — tu słup autostradowy, może być wyższy); ±40 %'),plaszcz=('0','brak podszytu i płaszcza — pnie widoczne od ziemi'))
f('PX24',typ='krawędź',el='DK19, młody bór sosnowy tuż przy poboczu',opis='Po prawej średniowiekowy drzewostan sosnowy tuż za żwirowym poboczem: pnie widoczne od ziemi, korony w górnej połowie, runo niskie (krzewinki/paprocie do ~1 m); dalej rząd brzóz o białych pniach. Po lewej świerk z koroną do ziemi i drzewa liściaste.',gat='sosna; brzoza; świerk',H=('14–18',HOR),plaszcz=('0','brak płaszcza; runo ≤1 m'))
f('PX26',typ='krawędź',el='DK19, ściana świerkowo-brzozowa za skarpą',opis='Po lewej wysokie sosny o gołych pniach. Po prawej trawiasta skarpa, za nią ściana świerków ze spiczastymi wierzchołkami i brzóz — linia nieba ząbkowana; u dołu widoczne pnie, bez pasa krzewów.',gat='świerk, brzoza; sosna po lewej',H=('18–22','proporcja do słupka prowadzącego (~1 m) przy tej samej głębi; ±40 %'),plaszcz=('0','brak; trawiasta skarpa 10–15 m (ESTIMATED) między jezdnią a pniami'))
f('PX30',typ='horyzont',el='DK19, kępy lasu za polem',opis='Otwarte pole po prawej; na horyzoncie osobne płaty lasu jako ciemne, zwarte bryły o łagodnie falistej, drobno ząbkowanej górnej linii, rozdzielone przerwą z niskimi krzewami. Po lewej pas zadrzewień z jaśniejszym liściastym skrajem. Żółty trójkątny znak z sylwetką jelenia (A-18b) z tabliczką i tył innej tablicy.',gat='sosna (sylwetka) — rodzaj ESTIMATED',H=None,plaszcz=(None,'z tej odległości niewidoczny'))
f('PX33',typ='krawędź',el='DK19, korytarz świerkowo-liściasty',opis='Droga w płytkim wykopie, trawiaste skarpy. Obie ściany zwarte: świerki z koroną nisko, po prawej warstwa liściasta zachodząca na skarpę; pod okapem widać pnie. Z naprzeciwka małe auto, słupek prowadzący.',gat='świerk, liściaste',H=('22–28','ściana ~15–18× wysokość auta (~1,5 m); ±30 %'),plaszcz=('0–2','brak osobnego pasa; gałęzie liściaste do ~1–2 m nad skarpą'))
f('PX35',typ='krawędź',el='DK19, brzozy i sosny przy rowie',opis='Po prawej brzozy o białych pniach i sosny o długich gołych pniach na samej krawędzi, pod nimi krzewy 1–3 m; trawiaste pobocze z rowem. Po lewej dęby/liściaste i sosny.',gat='brzoza, sosna, świerk w drugim piętrze',H=('22–26',HOR),plaszcz=('1–3','niski, nieciągły podszyt krzewów'))
f('PX37',typ='krawędź',el='DK19, stare sosny z podszytem',opis='Po lewej zwarty, ciemny bór sosnowy z widocznymi pniami. Po prawej duże sosny z rudą korą w górnej części pni, pochylone ku drodze, pod nimi krzewy i młode liściaste; trawiasta skarpa ~1 m nad jezdnią, biało-czerwone słupki.',gat='sosna',H=('22–28','krotność wysokości aut z naprzeciwka; ±30 %'),plaszcz=('2–4','krzewy i podrost liściasty 2–4 m pod sosnami'))
f('PX40',typ='horyzont',el='DK19, linia lasu za łąką',opis='Po prawej łąka z wysoką suchą trawą i kopkami; na horyzoncie ciągła, ciemna linia lasu z drobnymi ząbkami wierzchołków świerków. Po lewej drzewa w cieniu. Dwa auta, wieczorne światło.',gat='świerk/iglaste (sylwetka) — ESTIMATED',H=None,plaszcz=(None,'niewidoczny'))
