f('C151034288',typ='krawędź',el='Mickiewicza — brama lotniska, pas brzozowy (K5)',kier=(246,'prostopadle do osi ulicy (OSM 156°/336°), w stronę bramy lotniska po stronie SW; ±25°'),opis='Wlot z bramą (zielona stalowa, żółta tabliczka) naprzeciw kamery, za bramą otwarta płyta lotniska. Po prawej młodszy drzewostan brzozowo-osikowy o cienkich jasnych pniach, z gęstym piętrem krzewów do ziemi; po lewej zaokrąglone liściaste krzewy i drzewa. Dwie latarnie, biało-czerwone słupki, tył znaku A-7.',gat='brzoza/osika (jasne cienkie pnie)',H=('20–25 (prawa strona)','~2,3× wysokość latarni stojącej przed drzewami, z poprawką na głębię ×1,2; '+LAMP),plaszcz=('3–5','ciągły pas krzewów 3–5 m wys. do ziemi'))
f('C151034287',typ='krawędź',el='Mickiewicza — skraj lasu, kierunek miasto',kier=(336,MK.format(w=977514047)+'; dodatkowo lico znaku D-42 (obszar zabudowany) zwrócone do jadących ku miastu'),opis='Jezdnia po lewej z ciemnym autem, pas trawy ze znakiem D-42, asfaltowa droga rowerowa i chodnik z kostki. Po prawej ściana lasu: sosna i drzewa liściaste (na skraju korona o liściach zatokowo klapowanych jak u dębu) z podrostem do ziemi, przed nią 3–4 m trawy. Po lewej za jezdnią wysokie smukłe topole/osiki nad młodym liściastym zagajnikiem, niskie latarnie.',gat='sosna, dąb (ESTIMATED po liściu)/liściaste; topola/osika po lewej',H=('prawa ściana 18–24; topole 22–28','krotność wysokości latarni; '+LAMP),plaszcz=('0–2','podrost liściasty w linii drzew, bez osobnego pasa'))
f('C151034285',typ='krawędź',el='Mickiewicza — korytarz w Lesie Solnickim',kier=(156,MK.format(w=977514047)+' (droga rowerowa po lewej → patrzy na SE)'),opis='Dwupasowa jezdnia z krawężnikiem, latarnie po prawej. Prawa ściana: sosny w górze, pod nimi ciągła warstwa liściasta (klon, grab) do samej ziemi — pni nie widać; wąski pas trawy. Po lewej droga rowerowa z piktogramami, chodnik z kostki i rów umocniony ażurowymi płytami; las sosnowy z liściastym podszytem. Troje rowerzystów. Pochmurno.',gat='sosna + klon/grab w podszycie',H=('20–25','~2,2–2,6× wysokość latarni; '+LAMP+'; zgodne z BDL 152-a/163 (H 24–29 m)'),plaszcz=('0–1','brak pasa krzewów przed lasem; podszyt liściasty zamyka ścianę od ziemi'))
f('C151034286',typ='detal',el='Mickiewicza — skraj lasu z bliska (podszyt)',kier=('UNVERIFIED','kadr pionowy prostopadle do skraju; strona ulicy nieustalona'),opis='Zbliżenie skraju: piętrowo ułożone liście młodych klonów (klapowane) i krzewów od ziemi po korony, w lewym górnym rogu korona sosny. U dołu pas gołej, piaszczystej gleby ze ściółką i kępami trawy. Pni nie widać.',gat='klon (liście klapowane) — rodzaj rozpoznawalny; sosna w tle',H=None,plaszcz=('—','podszyt/podrost klonowy 0–8 m zamyka ścianę'))
f('C151034282',typ='krawędź',el='Mickiewicza — pnie przy krawędzi i młodnik',kier=(337,MK.format(w=977514047)),opis='Po lewej za jezdnią ściana lasu liściasto-iglastego: dwa pochylone pnie o jasnej korze gołe do kilku metrów, pod nimi krzewy 1–3 m, pas trawy. Po prawej droga rowerowa, chodnik i rów z ażurowych płyt; za nimi najpierw gęsty młody zagajnik liściasty, dalej wyższe brzozy i sosny — profil schodkowy. Ocynkowany słup latarni na pierwszym planie.',gat='liściaste (dąb/klon — UNVERIFIED), brzoza, sosna',H=('lewa 20–25; młodnik po prawej 5–8, drzewa za nim 18–22','krotność wysokości latarni; '+LAMP),plaszcz=('8–15 (prawa strona)','młodnik liściasty jako pas przed starszym drzewostanem'))
f('C151034281',typ='krawędź',el='Mickiewicza — brzozy i świerki / zwarty młodnik',kier=(337,MK.format(w=977514047)),opis='Po lewej ściana z brzóz (białe pnie), świerków i sosen; pnie widoczne do ~1/3 wysokości, niski podszyt, pas trawy 3–4 m, latarnie. Po prawej zwarta zielona ściana młodego drzewostanu liściastego, ulistniona do ziemi, o równej górnej linii. Droga rowerowa, chodnik z kostki, rów z płyt.',gat='brzoza, świerk, sosna; młodnik liściasty',H=('lewa 20–25; młodnik 6–10','krotność wysokości latarni; '+LAMP),plaszcz=('0 (lewa); cała ściana prawa to młodnik','po lewej tylko niski podszyt 1–2 m'))
f('C151034280',typ='krawędź',el='Mickiewicza — sosny i świerki, okap nad drogą rowerową',kier=(336,MK.format(w=977514047)),opis='Po lewej sosny, świerki i brzoza z widocznymi pniami, rzadki niski podszyt; ciemne auto i kolejne w głębi. Po prawej duże drzewa liściaste zwieszające gałęzie nad drogą rowerową, na skarpie ściółka z liści. Chodnik z kostki, rów umocniony płytami.',gat='sosna, świerk, brzoza; liściaste po prawej',H=('20–26','krotność wysokości latarni; '+LAMP),plaszcz=('0','brak; gałęzie drzew skrajnych nad drogą rowerową'))
f('C151034276',typ='krawędź',el='Mickiewicza — przystanek w lesie, znak A-18b',kier=(337,MK.format(w=977514050)+'; lico znaku A-18b z tabliczką „1,0 km” zwrócone do jadących ku miastu'),opis='Jezdnia z podwójną linią ciągłą. Po lewej ściana drzew liściastych z gałęziami zwieszonymi nisko, pnie widoczne, podszyt rzadki, grunt ~1 m nad jezdnią, pas trawy. Po prawej pochylona sosna z rudym pniem i brzozy za żółtą barierą, czerwona wiata przystanku; żółty trójkątny znak z sylwetką jelenia i tabliczką „1,0 km”.',gat='liściaste (dąb/grab — UNVERIFIED); sosna, brzoza',H=('20–26','krotność wysokości słupa latarni na pierwszym planie; '+LAMP),plaszcz=('0','brak płaszcza; rzadki podszyt'))
f('C151034274',typ='krawędź',el='Mickiewicza — przejście, las na skarpie',kier=(337,MK.format(w=977514050)),opis='Przejście dla pieszych, dwie latarnie różnego typu. Po lewej skarpa ~1,5–2 m ze ściółką i lasem: sosny z rudą korą, liściaste, pnie widoczne, podszyt niski. Po prawej brzozy i sosna na skraju, żółte barierki i wiata przystanku, żółty znak ostrzegawczy. Ciemne auto odjeżdża.',gat='sosna, brzoza, liściaste',H=('20–25','krotność wysokości latarni; '+LAMP),plaszcz=('0','brak; skarpa ze ściółką'))
