f('C136151960',typ='krawędź',el='Ciołkowskiego — płaszcz wierzbowy przy ciągu pieszo-rowerowym',kier=('UNVERIFIED','oś ulicy z OSM 62°/242° (way 691820499, 2,4 m od geotagu); zwrot nierozstrzygnięty (242° prawdopodobny z oświetlenia)'),opis='Asfaltowy ciąg pieszo-rowerowy (znak C-13/C-16). Po lewej zwarta ściana wierzb o wąskich, zwisających liściach, ulistniona do samej ziemi, oddzielona 2–3 m trawy; studzienka w trawie. Po prawej jezdnia, za nią rząd młodszych jasnozielonych drzew liściastych i latarnie.',gat='wierzba',H=('6–9','~3–4× wysokość znaku na słupku (~2,6 m do górnej krawędzi tarczy; ESTIMATED); ±30 %'),plaszcz=('cała ściana','zarośla wierzbowe = sam płaszcz, bez wyższego drzewostanu w kadrze'))
f('C136151965',typ='krawędź',el='Ciołkowskiego — S skraj Lasu Zwierzynieckiego (K2)',kier=(241,CK.format(s=269)+' — las (K2) po stronie NW jest po prawej'),opis='Jezdnia z sygnalizacją i przejściem; po lewej czterokondygnacyjny biurowiec (napis firmowy, nie odtwarzamy). Po prawej, tuż za chodnikiem/ciągiem z asfaltu i 2–3 m trawy, ciemna zwarta ściana lasu liściastego w cieniu, z koronami do ziemi, wyższa od latarni.',gat='liściaste (rodzaj UNVERIFIED — ściana w cieniu)',H=('18–24','~2× wysokość latarni dwuramiennej ('+LAMP+', tu słup wyższej klasy możliwy); zgodne z CHM p90 24,2 m (PTLZ 146d3d47)'),plaszcz=('0–2','brak osobnego pasa; gałęzie do ziemi'))
f('C94000148',typ='krawędź',el='Ciołkowskiego — świerki przy budynku i ściana lasu za jezdnią',kier=(61,CK.format(s=98)+' — słońce z prawej-przodu, cienie ogrodzenia ku lewej'),opis='Chodnik z kostki i asfaltowa droga rowerowa, trawnik, stalowe ogrodzenie. Po prawej trzykondygnacyjny budynek instytucji z antenami i 5 wysokimi świerkami o koronach prawie do ziemi (ok. 1,5–2× wysokość budynku). Po lewej za jezdnią równa, jasnozielona ściana lasu liściastego i latarnie.',gat='świerk (nasadzenie przy budynku); liściaste za jezdnią',H=('świerki 18–22; ściana po lewej 15–20','świerki ~1,7× budynek 3-kond. (~11 m, ESTIMATED 3,5 m/kond.); ściana ~2× latarnia; '+LAMP),plaszcz=('0','równa ściana do ziemi'))
f('C93999621',typ='krawędź',el='Ciołkowskiego (W) — bór sosnowy po obu stronach',kier=(241,CK.format(s=95)+' — lewa ściana pod światło, prawa oświetlona; bloki Nowego Miasta w osi'),opis='Dwie jezdnie, chodnik z kostki i asfaltowa droga rowerowa. Po prawej za jezdnią bór sosnowy: rude pnie widoczne, korony w górnej połowie, u podstawy oświetlony pas krzewów 2–3 m; wysoka latarnia dwuramienna. Po lewej, za pasem suchej wysokiej trawy, ciemna ściana sosen. W głębi bramownica sygnalizacji i bloki.',gat='sosna',H=('22–27','~2,2× wysokość latarni dwuramiennej na pierwszym planie (przyjęta 10–12 m, WORKING_VALUE); zgodne z BDL 146-a (SO 77 l., H 29 m)'),plaszcz=('2–4 (prawa); 15–20 m trawy (lewa)','niski pas krzewów pod sosnami; po lewej łąkowy pas zamiast krzewów'))
f('C93999325',typ='krawędź',el='Ciołkowskiego (W) — ściana lasu przy chodniku, tablica kierunkowa',kier=(61,CK.format(s=95)+' — prawa ściana pod światło'),opis='Duża zielona tablica drogowskazowa na dwóch słupach kratowych. Po prawej chodnik z kostki i ok. 5 m wysokich ziół, za nimi ciemna, zwarta ściana lasu pod światło. Po lewej za jezdniami sosny i drzewa liściaste, znaki P, droga rowerowa.',gat='sosna/liściaste (prawa ściana w cieniu — UNVERIFIED)',H=('20–26','~2,5–3× wysokość tablicy na słupach (~8 m do górnej krawędzi; ESTIMATED); ±30 %'),plaszcz=('~5 (zioła)','pas wysokich ziół/traw zamiast krzewów'))
f('C149115308',typ='krawędź',el='Ciołkowskiego — ściana Lasu Solnickiego w poprzek jezdni (lato)',kier=(151,'prostopadle do osi ulicy (OSM 61°/241°), ku lasowi po stronie SE (BDL oddz. 144); ±25°'),opis='Widok w poprzek dwóch jezdni z pasem trawy; ciemne auto po lewej i dwa jasne z prawej. Ściana lasu: u podstawy ciągły, jasnozielony pas młodych liściastych i krzewów, nad nim ciemniejsze korony drzew liściastych i sosny (widoczny jeden rudy pień). Na pierwszym planie pień i gałęzie drzewa liściastego, trawnik.',gat='liściaste + sosna',H=('22–27; płaszcz 2,5–4','krotność wysokości auta (1,45 m) na dalszej jezdni × poprawka na głębię 1,6–1,8; ±30 %; zgodne z BDL 144-a (H 28 m)'),plaszcz=('3–6','ciągły pas młodnika/krzewów 2,5–4 m wys.'))
f('C149115310',typ='krawędź',el='Ciołkowskiego/Wiosenna — sosny za skrzyżowaniem (lato)',kier=('UNVERIFIED','skrzyżowanie; kierunek nieustalony (to samo miejsce co C116087673)'),opis='Skrzyżowanie z sygnalizacją, przejściami i przejazdami rowerowymi (czerwona nawierzchnia), rowerzyści i auta, burzowe chmury. W tle po prawej zwarty bór sosnowy: pnie gołe na ~60 % wysokości, korony ciemnozielone u góry, u podstawy niższa zieleń liściasta. Po lewej samotna sosna o parasolowatej koronie i drzewa liściaste. Znaki B-33 „70” i żółte trójkąty.',gat='sosna',H=('22–28','~2–2,5× wysokość latarni przed lasem; '+LAMP+'; BDL 144-a: SO 77 l., H 28 m'),plaszcz=('2–4','zielony pas liściasty u podstawy pni'))
f('C116087673',typ='krawędź',el='Ciołkowskiego/Wiosenna — sosny za skrzyżowaniem (przedwiośnie)',kier=('UNVERIFIED','skrzyżowanie; kierunek nieustalony'),opis='To samo skrzyżowanie bez liści: wysięgnik sygnalizacji widziany od tyłu, znaki B-33 „70” z żółtymi trójkątami, auta. Sosny jako ciemnozielone korony na szarobrązowych pniach gołych do ~2/3 wysokości; po lewej bezlistne drzewa liściaste jako szarobrązowa, prześwitująca masa. Niebo zachmurzone, płaskie światło.',gat='sosna; liściaste bezlistne',H=('22–28','jak C149115310'),plaszcz=('—','zimą pas krzewów prześwituje — widać pnie do ziemi'))
f('C131135940',typ='krawędź',el='Wiosenna/Ciołkowskiego — prześwietlony rząd sosen (kwiecień)',kier=('UNVERIFIED','zdjęcie z jadącego pojazdu (odbicie w szybie)'),opis='Kilkanaście sosen na trawniku ze ściółką: pnie gołe do 60–70 % wysokości, korony ażurowe, bez podszytu. Za nimi chodnik, siatka, szare pawilony targowe i auta. Pochmurno.',gat='sosna',H=('18–24','~12–15× wysokość auta (1,45 m) stojącego tuż za drzewami; ±30 %'),plaszcz=('0','brak podszytu — trawnik/ściółka'))
f('C131135942',typ='krawędź',el='Wiosenna/Ciołkowskiego — bezlistne liściaste i sosny (kwiecień)',kier=('UNVERIFIED','zdjęcie z jadącego pojazdu'),opis='Bezlistne drzewa liściaste (cienkie pnie, miotlaste korony) i dwie sosny o wysoko osadzonych koronach; rowerzysta na chodniku, za siatką parking i pawilony. Szare niebo.',gat='liściaste bezlistne; sosna',H=('15–20','krotność wysokości rowerzysty (~1,8 m); ±30 %'),plaszcz=('0','brak'))
# ---------- Commons: Dywizjonu 303 (horyzont) ----------
f('C136151985',typ='horyzont',el='Dywizjonu 303 — horyzont lasu (kadr P11-056)',kier=(0,'kadr prostopadły do osi ulicy (OSM way 443103344: 91°/271°); słońce (azymut 272° o 17:57 CEST) oświetla scenę z lewej → patrzy na N; ±30°'),opis='Na pierwszym planie jezdnia, za nią wlot z przejściem i przejazdem (czerwona nawierzchnia), latarnie, tablica z nazwą ulicy, znak D-6, tablica informacyjna, ciemne auto. Lewa część horyzontu: ciągły, ciemny pas lasu o gładkiej, łagodnie falistej górnej linii, przed nim jaśniejsze zaokrąglone korony zarośli; na prawym końcu pasa cienka wieża i czerwone dachy. Prawa część: luźny rząd pojedynczych zaokrąglonych koron liściastych nad łanem żółtozielonych ziół. Brak budynków wyższych od linii drzew.',gat='UNVERIFIED (odległość ~0,6–1 km)',H=None,plaszcz=(None,'dwie warstwy tonalne: jaśniejsze zarośla z przodu, ciemny las za nimi'))
f('C136151967',typ='horyzont',el='Dywizjonu 303 — rondo, linia lasu za lotniskiem',kier=('UNVERIFIED','geotag 9 m od osi; z cieni i położenia lotniska prawdopodobnie ku SE (≈135°), nierozstrzygnięte'),opis='Rondo z trawiastą wyspą, przejście dla pieszych, znaki (A-7 z C-12, D-6, tablice z biało-czerwonymi strzałami). Za rondem płaska otwarta przestrzeń; na całej szerokości horyzontu ciągły, równy, ciemny pas lasu — w kadrze cienki (ok. 2 % wysokości obrazu), bez ząbków. Z prawej bliska, zaokrąglona korona dużego drzewa liściastego. Niebo z cumulusami.',gat='UNVERIFIED',H=None,plaszcz=(None,'niewidoczny'))
f('C136151968',typ='horyzont',el='Dywizjonu 303 — łąka ruderalna, otwarty horyzont',kier=('UNVERIFIED','—'),opis='Łan wysokich ziół: żółto kwitnące (jak nawłoć), brązowe kwiatostany szczawiu, białe baldachy; chodnik z betonowej kostki. W głębi biała hala w budowie za szarym ogrodzeniem i latarnie dwuramienne. Horyzont po lewej: bardzo cienka ciemna linia drzew i jedno młode drzewko; brak ściany lasu.',gat='—',H=None,plaszcz=(None,'—'))
f('C94000344',typ='horyzont',el='Ciołkowskiego/Dywizjonu 303 — nowa jezdnia, niski horyzont drzew',kier=('UNVERIFIED','—'),opis='Szeroka nowa jezdnia z chodnikiem z kostki, latarnie dwuramienne, znaki D-3. Po lewej drewniane domy z żywopłotami i pojedyncze drzewa liściaste; w osi drogi nisko nad horyzontem cienka ciemna linia drzew; po prawej dalekie kępy drzew. Bezchmurnie, rano.',gat='—',H=None,plaszcz=(None,'—'))
